const triggerData = $('Execute Workflow Trigger').first().json || {};
const sheetRows = $input.all();

// 1. Resilient input extraction (supports nested query or flat parameters)
const queryObj = triggerData.query || {};
const action = (triggerData.action || queryObj.action || 'list').toLowerCase().trim();
const sheetId = triggerData.sheetId || queryObj.sheetId || '';
const goalNameInput = (triggerData.name || triggerData.goalName || queryObj.name || queryObj.goalName || triggerData.goal || queryObj.goal || '').trim();
const goalIdInput = (triggerData.goalId || queryObj.goalId || '').trim();
const targetAmountRaw = triggerData.targetAmount !== undefined ? triggerData.targetAmount : (queryObj.targetAmount !== undefined ? queryObj.targetAmount : (triggerData.amount || queryObj.amount));
const targetAmount = targetAmountRaw !== undefined && targetAmountRaw !== null ? parseFloat(targetAmountRaw) : null;
const currentSavedRaw = triggerData.currentSaved !== undefined ? triggerData.currentSaved : queryObj.currentSaved;
const initialSaved = currentSavedRaw !== undefined && currentSavedRaw !== null ? parseFloat(currentSavedRaw) : 0;
const amountToAddRaw = triggerData.amountToAdd !== undefined ? triggerData.amountToAdd : (queryObj.amountToAdd !== undefined ? queryObj.amountToAdd : (triggerData.saved || queryObj.saved));
const amountToAdd = amountToAddRaw !== undefined && amountToAddRaw !== null ? parseFloat(amountToAddRaw) : 0;
const targetDateInput = triggerData.targetDate || queryObj.targetDate || triggerData.deadline || queryObj.deadline || '';
const notesInput = triggerData.notes || queryObj.notes || '';
const statusInput = triggerData.status || queryObj.status || 'active';

// 2. Check if sheet read threw an error (e.g. Goals tab missing)
const firstItem = sheetRows[0]?.json || {};
if (firstItem.error) {
  return [{
    json: {
      operationType: 'read_only',
      success: false,
      status: 'SHEET_TAB_NOT_FOUND',
      response: "⚠️ The 'Goals' tab was not found in your Google Sheet. Please ensure a tab named 'Goals' exists with columns: goalId, name, targetAmount, currentSaved, monthlyContribution, targetDate, status, lastMilestone, createdAt, updatedAt, notes.",
      error: firstItem.error
    }
  }];
}

// 3. Filter valid active goals from sheet
const existingGoals = sheetRows
  .map(r => r.json)
  .filter(g => g && g.name && g.targetAmount !== undefined && g.row_number !== undefined);

// Helper: Calculate deterministic metrics
function calculateGoalMetrics(targetAmt, currSaved, tgtDateStr) {
  const now = new Date();
  const target = Math.max(0, parseFloat(targetAmt) || 0);
  const saved = Math.max(0, parseFloat(currSaved) || 0);
  const remaining = Math.max(0, target - saved);

  let monthsRemaining = 6; // sensible default if no date specified
  if (tgtDateStr) {
    const tDate = new Date(tgtDateStr);
    if (!isNaN(tDate.getTime())) {
      const diffDays = Math.max(0, (tDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      monthsRemaining = Math.max(1, Math.ceil(diffDays / 30.4375));
    }
  }

  const monthlyContribution = remaining > 0 ? Math.round(remaining / monthsRemaining) : 0;
  const percentage = target > 0 ? Math.min(100, Math.round((saved / target) * 100)) : 0;

  return { target, saved, remaining, monthsRemaining, monthlyContribution, percentage };
}

// Helper: Evaluate milestone crossing (25%, 50%, 75%, 100%)
function evaluateMilestone(priorMilestone, currentPercentage, name, saved, target) {
  const prior = parseFloat(priorMilestone) || 0;
  let achieved = 0;
  if (currentPercentage >= 100) achieved = 100;
  else if (currentPercentage >= 75) achieved = 75;
  else if (currentPercentage >= 50) achieved = 50;
  else if (currentPercentage >= 25) achieved = 25;

  if (achieved > prior) {
    let alertMsg = '';
    if (achieved === 100) {
      alertMsg = `🎯 GOAL COMPLETED! Congratulations, you have fully reached 100% of your "${name}" goal (₹${saved.toLocaleString('en-IN')} / ₹${target.toLocaleString('en-IN')})! 🚀🎉`;
    } else {
      alertMsg = `🎯 Milestone Reached! You have completed ${achieved}% of your "${name}" goal (₹${saved.toLocaleString('en-IN')} / ₹${target.toLocaleString('en-IN')} saved). Keep it up! 💪✨`;
    }
    return { milestoneCrossed: achieved, newLastMilestone: achieved, milestoneAlert: alertMsg };
  }
  return { milestoneCrossed: null, newLastMilestone: prior, milestoneAlert: null };
}

// 4. Dispatch Actions

// ACTION: CREATE
if (action === 'create' || action === 'add' || action === 'set') {
  if (!goalNameInput) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'MISSING_NAME',
        response: '⚠️ Please specify a name for the goal (e.g., "Emergency Fund", "MacBook").'
      }
    }];
  }
  if (!targetAmount || targetAmount <= 0) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'INVALID_AMOUNT',
        response: '⚠️ Please provide a valid target amount greater than 0.'
      }
    }];
  }

  // Check if a goal with exact same name already exists
  const duplicate = existingGoals.find(g => (g.name || '').toLowerCase() === goalNameInput.toLowerCase() && g.status !== 'cancelled');
  if (duplicate) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'ALREADY_EXISTS',
        response: `⚠️ A goal named "${goalNameInput}" already exists with target ₹${duplicate.targetAmount} (Saved: ₹${duplicate.currentSaved || 0}). Use 'add_savings' to contribute or update it.`
      }
    }];
  }

  const nowIso = new Date().toISOString();
  const metrics = calculateGoalMetrics(targetAmount, initialSaved, targetDateInput);
  const milestoneResult = evaluateMilestone(0, metrics.percentage, goalNameInput, metrics.saved, metrics.target);
  const newGoalId = `goal_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;

  const newRow = {
    goalId: newGoalId,
    name: goalNameInput,
    targetAmount: metrics.target,
    currentSaved: metrics.saved,
    monthlyContribution: metrics.monthlyContribution,
    targetDate: targetDateInput || '',
    status: metrics.saved >= metrics.target ? 'completed' : 'active',
    lastMilestone: milestoneResult.newLastMilestone,
    createdAt: nowIso,
    updatedAt: nowIso,
    notes: notesInput
  };

  let respMsg = `🎯 Goal Created: "${goalNameInput}" with target ₹${metrics.target.toLocaleString('en-IN')}`;
  if (targetDateInput) respMsg += ` by ${targetDateInput}`;
  respMsg += `.\nMonthly contribution required: ₹${metrics.monthlyContribution.toLocaleString('en-IN')}/month (${metrics.monthsRemaining} months). Current progress: ${metrics.percentage}% (₹${metrics.saved.toLocaleString('en-IN')}).`;
  if (milestoneResult.milestoneAlert) respMsg += `\n\n${milestoneResult.milestoneAlert}`;

  return [{
    json: {
      operationType: 'append',
      sheetId,
      goal: newRow,
      response: respMsg,
      milestoneAlert: milestoneResult.milestoneAlert,
      ...newRow
    }
  }];
}

// ACTION: ADD_SAVINGS (Update progress)
if (action === 'add_savings' || action === 'contribute' || action === 'deposit' || action === 'save') {
  if (amountToAdd <= 0) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'INVALID_AMOUNT',
        response: '⚠️ Please provide an amount to add greater than 0.'
      }
    }];
  }

  // Pinpoint goal
  let matchedGoal = null;
  if (goalIdInput) {
    matchedGoal = existingGoals.find(g => g.goalId === goalIdInput);
  } else if (goalNameInput) {
    const cleanSearch = goalNameInput.toLowerCase();
    matchedGoal = existingGoals.find(g => (g.name || '').toLowerCase() === cleanSearch) ||
                  existingGoals.find(g => (g.name || '').toLowerCase().includes(cleanSearch));
  } else if (existingGoals.length === 1) {
    matchedGoal = existingGoals[0];
  }

  if (!matchedGoal) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'GOAL_NOT_FOUND',
        response: `⚠️ Could not find an active goal matching "${goalNameInput || 'your query'}". Please check your active goals!`
      }
    }];
  }

  const prevSaved = parseFloat(matchedGoal.currentSaved) || 0;
  const newSaved = prevSaved + amountToAdd;
  const tgtAmount = parseFloat(matchedGoal.targetAmount) || 0;
  const tgtDate = matchedGoal.targetDate || '';

  const metrics = calculateGoalMetrics(tgtAmount, newSaved, tgtDate);
  const milestoneResult = evaluateMilestone(matchedGoal.lastMilestone || 0, metrics.percentage, matchedGoal.name, metrics.saved, metrics.target);

  const updatedStatus = metrics.saved >= metrics.target ? 'completed' : (matchedGoal.status || 'active');
  const nowIso = new Date().toISOString();

  const updatedRow = {
    row_number: matchedGoal.row_number,
    goalId: matchedGoal.goalId,
    name: matchedGoal.name,
    targetAmount: metrics.target,
    currentSaved: metrics.saved,
    monthlyContribution: metrics.monthlyContribution,
    targetDate: tgtDate,
    status: updatedStatus,
    lastMilestone: milestoneResult.newLastMilestone,
    createdAt: matchedGoal.createdAt || nowIso,
    updatedAt: nowIso,
    notes: notesInput || matchedGoal.notes || ''
  };

  let respMsg = `💰 Added ₹${amountToAdd.toLocaleString('en-IN')} to "${matchedGoal.name}"! Total saved: ₹${metrics.saved.toLocaleString('en-IN')} / ₹${metrics.target.toLocaleString('en-IN')} (${metrics.percentage}%).\nMonthly contribution needed now: ₹${metrics.monthlyContribution.toLocaleString('en-IN')}/mo.`;
  if (milestoneResult.milestoneAlert) respMsg += `\n\n${milestoneResult.milestoneAlert}`;

  return [{
    json: {
      operationType: 'update',
      sheetId,
      row_number: matchedGoal.row_number,
      goal: updatedRow,
      response: respMsg,
      milestoneAlert: milestoneResult.milestoneAlert,
      ...updatedRow
    }
  }];
}

// ACTION: LIST or GET
if (action === 'list' || action === 'get' || action === 'show' || action === 'query') {
  const activeGoals = existingGoals.filter(g => g.status !== 'cancelled');
  if (activeGoals.length === 0) {
    return [{
      json: {
        operationType: 'read_only',
        success: true,
        status: 'EMPTY',
        response: "You don't have any financial goals set up yet. You can create one anytime by saying: 'Create goal: Laptop ₹60,000 by December'!",
        goals: []
      }
    }];
  }

  let summaryStr = `🎯 Here are your financial goals (${activeGoals.length} total):\n\n`;
  const enrichedGoals = activeGoals.map(g => {
    const metrics = calculateGoalMetrics(g.targetAmount, g.currentSaved, g.targetDate);
    const statusIcon = g.status === 'completed' ? '✅' : '⏳';
    summaryStr += `${statusIcon} **${g.name}**: ₹${metrics.saved.toLocaleString('en-IN')} / ₹${metrics.target.toLocaleString('en-IN')} (${metrics.percentage}%)\n`;
    if (g.targetDate) summaryStr += `  • Target: ${g.targetDate} (${metrics.monthsRemaining} months left)\n`;
    if (metrics.remaining > 0) summaryStr += `  • Monthly contribution needed: ₹${metrics.monthlyContribution.toLocaleString('en-IN')}/mo\n`;
    else summaryStr += `  • Goal achieved! 🎉\n`;
    summaryStr += `\n`;
    return { ...g, ...metrics };
  });

  return [{
    json: {
      operationType: 'read_only',
      success: true,
      status: 'SUCCESS',
      response: summaryStr.trim(),
      goals: enrichedGoals
    }
  }];
}

// ACTION: CANCEL / DELETE
if (action === 'delete' || action === 'cancel' || action === 'remove') {
  let matchedGoal = null;
  if (goalIdInput) matchedGoal = existingGoals.find(g => g.goalId === goalIdInput);
  else if (goalNameInput) {
    const clean = goalNameInput.toLowerCase();
    matchedGoal = existingGoals.find(g => (g.name || '').toLowerCase() === clean) ||
                  existingGoals.find(g => (g.name || '').toLowerCase().includes(clean));
  }

  if (!matchedGoal) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'GOAL_NOT_FOUND',
        response: `⚠️ Could not find any goal matching "${goalNameInput || 'your query'}" to delete.`
      }
    }];
  }

  const updatedRow = {
    row_number: matchedGoal.row_number,
    goalId: matchedGoal.goalId,
    name: matchedGoal.name,
    targetAmount: matchedGoal.targetAmount,
    currentSaved: matchedGoal.currentSaved,
    monthlyContribution: 0,
    targetDate: matchedGoal.targetDate || '',
    status: 'cancelled',
    lastMilestone: matchedGoal.lastMilestone || 0,
    createdAt: matchedGoal.createdAt || new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    notes: `[CANCELLED] ${matchedGoal.notes || ''}`
  };

  return [{
    json: {
      operationType: 'update',
      sheetId,
      row_number: matchedGoal.row_number,
      goal: updatedRow,
      response: `Successfully cancelled the goal "${matchedGoal.name}".`,
      ...updatedRow
    }
  }];
}

// Default fallback
return [{
  json: {
    operationType: 'read_only',
    success: false,
    status: 'UNKNOWN_ACTION',
    response: `Unknown action "${action}". Supported actions: create, add_savings, list, delete.`
  }
}];

const proc = $('Process Goal Action').first().json;
return {
  json: {
    success: true,
    status: 'CREATED',
    action: 'create',
    response: proc.response,
    milestoneAlert: proc.milestoneAlert,
    goal: proc.goal
  }
};

const proc = $('Process Goal Action').first().json;
return {
  json: {
    success: true,
    status: 'UPDATED',
    action: proc.action || 'update',
    response: proc.response,
    milestoneAlert: proc.milestoneAlert,
    goal: proc.goal
  }
};

const proc = $input.first().json;
return {
  json: {
    success: proc.success !== undefined ? proc.success : true,
    status: proc.status || 'OK',
    action: proc.action || 'list',
    response: proc.response || 'Operation completed',
    goals: proc.goals || [],
    error: proc.error || null
  }
};
